372	
373	        // 同 requestId 改站 -> 409
374	        postJson("/api/bags/recover", Map.of("requestId", requestId,
375	                "bagTag", "BAG1", "missingLegId", "LEG1", "actualStation", "CAN"))
376	                .andExpect(status().isConflict());
377	
378	        // 失败不占键：短卸行李先以错误站失败（422），再用同键正确参数成功
379	        registerLeg("LEG3", "PEK", "SHA");
380	        registerBag("BAG3", List.of("LEG3"));
381	        load("LEG3", 1, List.of("BAG3"));
382	        seal("LEG3", 2);
383	        diffArrive("LEG3", 3, List.of()).andExpect(status().isOk());
384	
385	        String retryKey = UUID.randomUUID().toString();
386	        postJson("/api/bags/recover", Map.of("requestId", retryKey,
387	                "bagTag", "BAG3", "missingLegId", "LEG3", "actualStation", "CAN"))
388	                .andExpect(status().isUnprocessableEntity());
389	        postJson("/api/bags/recover", Map.of("requestId", retryKey,
390	                "bagTag", "BAG3", "missingLegId", "LEG3", "actualStation", "SHA"))
391	                .andExpect(status().isOk())
392	                .andExpect(jsonPath("$.status").value("DELIVERED"));
393	    }
394	
395	    @Test
396	    void concurrentRecoverAndLoad_consistentOrdering() throws Exception {
397	        registerLeg("LEG1", "PEK", "SHA");
398	        registerLeg("LEG2", "SHA", "CAN");
399	        registerBag("BAG_SHORT", List.of("LEG1", "LEG2"));
400	        registerBag("BAG_OK", List.of("LEG2"));
401	        load("LEG1", 1, List.of("BAG_SHORT"));
402	        seal("LEG1", 2);
403	        diffArrive("LEG1", 3, List.of()).andExpect(status().isOk());
404	
405	        // 补到与后续航段批量装载真实并发：顺序只能是“装载失败整批不移动”或“补到先提交后装载成功”
406	        List<Callable<Object>> tasks = List.of(
407	                () -> baggageService.recover(new RecoverRequest(
408	                        UUID.randomUUID().toString(), "BAG_SHORT", "LEG1", "SHA")),
409	                () -> baggageService.load("LEG2",
410	                        new LoadRequest(UUID.randomUUID().toString(), 1,
411	                                List.of("BAG_OK", "BAG_SHORT"))));
412	        List<Object> results = runConcurrently(tasks);
413	
414	        boolean loadSucceeded = results.stream()
415	                .anyMatch(r -> r instanceof com.example.starter.baggage.BaggageDtos.LoadResponse);
416	        boolean loadFailed = results.stream()
417	                .filter(ApiException.class::isInstance)
418	                .map(ApiException.class::cast)
419	                .anyMatch(ex -> ex.getStatus().value() == 422);
420	        assertThat(loadSucceeded).isNotEqualTo(loadFailed);
421	
422	        Integer okLoaded = jdbcTemplate.queryForObject(
423	                "SELECT COUNT(*) FROM load_record WHERE bag_tag = 'BAG_OK'", Integer.class);
424	        if (loadSucceeded) {
425	            // 补到先提交：整批两件都进入清单
426	            assertThat(okLoaded).isEqualTo(1);
427	            Integer shortLoaded = jdbcTemplate.queryForObject(
428	                    "SELECT COUNT(*) FROM load_record WHERE bag_tag = 'BAG_SHORT'", Integer.class);
429	            assertThat(shortLoaded).isEqualTo(1);
430	            String shortStatus = jdbcTemplate.queryForObject(
431	                    "SELECT status FROM bag WHERE bag_tag = 'BAG_SHORT'", String.class);
432	            assertThat(shortStatus).isEqualTo("RECOVERED");
433	        } else {
434	            // 装载先尝试且失败：整批不移动，补到完成后再装载必然成功
435	            assertThat(okLoaded).isZero();
436	            recover("BAG_SHORT", "LEG1", "SHA").andExpect(status().isOk());
437	            load("LEG2", 1, List.of("BAG_OK", "BAG_SHORT")).andExpect(status().isOk());
438	        }
439	    }
